import { readFileSync, readdirSync } from "node:fs";
import path from "node:path";
import type { CraftingModifiers, GameConstants, Item } from "@apc/game-data";
import { type Catalog, createCatalog } from "../src/catalog.ts";

const GENERATED = path.join(import.meta.dirname, "../../game-data/generated");

function readJson<T>(file: string): T {
    return JSON.parse(readFileSync(path.join(GENERATED, file), "utf8")) as T;
}

/** The real catalog generated by @apc/game-data */
export function loadCatalog(): Catalog {
    const items = readdirSync(path.join(GENERATED, "items")).flatMap((file) =>
        readJson<Item[]>(`items/${file}`),
    );

    return createCatalog(
        items,
        readJson<CraftingModifiers>("crafting-modifiers.json"),
        readJson<GameConstants>("game-constants.json"),
    );
}

export function getItem(catalog: Catalog, uniqueName: string): Item {
    const item = catalog.item(uniqueName);

    if (!item) {
        throw new Error(`No ${uniqueName} in the catalog`);
    }

    return item;
}

export const CLUSTERS = {
    Thetford: "0000",
    Lymhurst: "1000",
    Bridgewatch: "2000",
    Martlock: "3004",
    "Fort Sterling": "4000",
    Caerleon: "3003",
    Brecilien: "5000",
} as const;

export type City = keyof typeof CLUSTERS;

/** Deterministic pseudo-random price for a market id */
export function fakePrice(marketId: string, salt = ""): number {
    let hash = 2166136261;

    for (const char of `${salt}:${marketId}`) {
        hash = Math.imul(hash ^ char.charCodeAt(0), 16777619);
    }

    return 100 + ((hash >>> 0) % 50_000);
}
